//! the gui's pixel icons drawn in character cells with half blocks: each cell shows two pixels
//! stacked, the top one as the `▀` glyph's colour and the bottom one as the cell background.
//!
//! the art is not copied: crates/ui/src/icon_data.rs (generated by tools/make-icons.py) is
//! included here by path, so the gui and the terminal draw from the same file.

use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::widgets::Widget;

use super::palette::{art_rgb, Palette, Rgb};

#[allow(dead_code)]
mod data {
    include!("../../../ui/src/icon_data.rs");
}

/// the 32 by 32 icon for a module or window id, with the same fallback as the gui.
pub fn art(id: &str) -> &'static [&'static str] {
    match id {
        "gateway" => &data::GATEWAY,
        "docker" => &data::DOCKER,
        "nt4-domain" => &data::NT4,
        "web-proxy" => &data::WEB,
        "remote-commands" => &data::COMMANDS,
        "dns" => &data::DNS,
        "console" => &data::CONSOLE,
        "settings" => &data::SETTINGS,
        "folder" => &data::FOLDER,
        "my-server" => &data::MYSERVER,
        "networks" => &data::NETWORKS,
        _ => &data::HOSTS,
    }
}

/// the 16 by 16 icon for the same ids, plus "lanlord" for the menu button.
pub fn small(id: &str) -> &'static [&'static str] {
    match id {
        "gateway" => &data::SMALL_GATEWAY,
        "docker" => &data::SMALL_DOCKER,
        "nt4-domain" => &data::SMALL_NT4,
        "web-proxy" => &data::SMALL_WEB,
        "remote-commands" => &data::SMALL_COMMANDS,
        "dns" => &data::SMALL_DNS,
        "console" => &data::SMALL_CONSOLE,
        "settings" => &data::SMALL_SETTINGS,
        "folder" => &data::SMALL_FOLDER,
        "my-server" => &data::SMALL_MYSERVER,
        "networks" => &data::SMALL_NETWORKS,
        "lanlord" => &data::SMALL_LANLORD,
        "update" => &data::SMALL_UPDATE,
        _ => &data::SMALL_HOSTS,
    }
}

/// the pixel at (`x`, `y`) of `art` shrunk by `step`: the most common opaque colour in the
/// step by step block, or transparent when most of the block is.
fn sample(art: &[&str], x: usize, y: usize, step: usize) -> Option<Rgb> {
    let mut counts: Vec<(Rgb, usize)> = Vec::new();
    let mut clear = 0;
    for row in art.iter().skip(y * step).take(step) {
        for c in row.chars().skip(x * step).take(step) {
            match art_rgb(c) {
                Some(rgb) => match counts.iter_mut().find(|(seen, _)| *seen == rgb) {
                    Some((_, n)) => *n += 1,
                    None => counts.push((rgb, 1)),
                },
                None => clear += 1,
            }
        }
    }
    let (rgb, most) = counts.into_iter().max_by_key(|(_, n)| *n)?;
    (most >= clear || clear * 2 < step * step).then_some(rgb)
}

/// one terminal cell of an icon: the glyph and its two colours, or `None` to leave the cell
/// as it is (both pixels transparent).
pub type ArtCell = Option<(&'static str, Option<Rgb>, Option<Rgb>)>;

/// the cells of `art` shrunk by `step` (1 keeps every pixel): `width / step` cells across and
/// `height / step / 2` down, since each cell holds two pixels stacked.
pub fn cells(art: &[&str], step: usize) -> Vec<Vec<ArtCell>> {
    let step = step.max(1);
    let width = art.first().map_or(0, |row| row.chars().count()) / step;
    let height = art.len() / step;
    (0..height.div_ceil(2))
        .map(|row| {
            (0..width)
                .map(|x| {
                    let top = sample(art, x, row * 2, step);
                    let bottom = if row * 2 + 1 < height {
                        sample(art, x, row * 2 + 1, step)
                    } else {
                        None
                    };
                    match (top, bottom) {
                        (None, None) => None,
                        (Some(t), b) => Some(("▀", Some(t), b)),
                        (None, Some(b)) => Some(("▄", Some(b), None)),
                    }
                })
                .collect()
        })
        .collect()
}

/// an icon drawn at the top-left of its area; transparent pixels show the cell's existing
/// background.
pub struct Icon<'a> {
    pub art: &'a [&'a str],
    pub step: usize,
    pub palette: Palette,
}

impl Icon<'_> {
    /// how many cells the icon covers: (columns, rows).
    pub fn size(&self) -> (u16, u16) {
        let step = self.step.max(1);
        let width = self.art.first().map_or(0, |row| row.chars().count()) / step;
        let height = (self.art.len() / step).div_ceil(2);
        (width as u16, height as u16)
    }
}

impl Widget for Icon<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        for (dy, row) in cells(self.art, self.step).iter().enumerate() {
            for (dx, cell) in row.iter().enumerate() {
                let (x, y) = (area.x + dx as u16, area.y + dy as u16);
                if x >= area.right() || y >= area.bottom() {
                    continue;
                }
                let (Some((glyph, fg, bg)), Some(target)) = (cell, buf.cell_mut((x, y))) else {
                    continue;
                };
                target.set_symbol(glyph);
                if let Some(fg) = fg {
                    target.fg = self.palette.color(*fg);
                }
                if let Some(bg) = bg {
                    target.bg = self.palette.color(*bg);
                }
            }
        }
    }
}

/// the colour that stands for an icon at one cell: its most used colour that is not black,
/// white or gray, or its most used colour when it has nothing else.
pub fn accent(art: &[&str]) -> Option<Rgb> {
    let mut counts: Vec<(char, usize)> = Vec::new();
    for c in art.iter().flat_map(|row| row.chars()) {
        if art_rgb(c).is_none() {
            continue;
        }
        match counts.iter_mut().find(|(seen, _)| *seen == c) {
            Some((_, n)) => *n += 1,
            None => counts.push((c, 1)),
        }
    }
    counts.sort_by_key(|(_, n)| std::cmp::Reverse(*n));
    let plain = |c: char| matches!(c, 'k' | 'w' | 'g' | 'd');
    counts
        .iter()
        .find(|(c, _)| !plain(*c))
        .or_else(|| counts.first())
        .and_then(|(c, _)| art_rgb(*c))
}

/// an icon squeezed into one cell for title bars, the taskbar and menus: a square in the
/// icon's accent colour on `bg`, where the gui draws the 16 by 16 art.
pub fn badge(buf: &mut Buffer, x: u16, y: u16, art: &[&str], bg: Rgb, palette: Palette) {
    let (Some(rgb), Some(cell)) = (accent(art), buf.cell_mut((x, y))) else {
        return;
    };
    cell.set_symbol("■");
    cell.fg = palette.color(rgb);
    cell.bg = palette.color(bg);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::paint::palette::{Depth, BLACK, WHITE};
    use ratatui::style::Color;

    const TINY: [&str; 4] = ["kw..", "kw..", "..ww", "...."];

    #[test]
    fn two_pixels_stack_into_one_half_block_cell() {
        let rows = cells(&TINY, 1);
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0][0], Some(("▀", Some(BLACK), Some(BLACK))));
        assert_eq!(rows[0][1], Some(("▀", Some(WHITE), Some(WHITE))));
        assert_eq!(rows[0][2], None, "both pixels transparent");
        // only the top pixel: the glyph's colour is the top, the background stays
        assert_eq!(rows[1][2], Some(("▀", Some(WHITE), None)));
    }

    #[test]
    fn a_lone_bottom_pixel_uses_the_lower_half_block() {
        let art = ["..", "kk"];
        assert_eq!(cells(&art, 1)[0][0], Some(("▄", Some(BLACK), None)));
    }

    #[test]
    fn shrinking_keeps_the_dominant_colour_of_each_block() {
        let rows = cells(&TINY, 2);
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].len(), 2);
        let Some((_, Some(top), _)) = rows[0][0] else {
            panic!("the left block is opaque");
        };
        assert!(top == BLACK || top == WHITE);
    }

    #[test]
    fn the_gui_icons_fit_their_cell_sizes() {
        let palette = Palette::new(Depth::TrueColor);
        let desktop = Icon {
            art: art("my-server"),
            step: 2,
            palette,
        };
        assert_eq!(desktop.size(), (16, 8));
        let title = Icon {
            art: small("lanlord"),
            step: 8,
            palette,
        };
        assert_eq!(title.size(), (2, 1));
        assert_eq!(art("unknown"), art("hosts"));
    }

    #[test]
    fn rendering_paints_the_pixels_and_skips_transparent_cells() {
        let mut buf = Buffer::empty(Rect::new(0, 0, 4, 2));
        Icon {
            art: &TINY,
            step: 1,
            palette: Palette::new(Depth::TrueColor),
        }
        .render(buf.area, &mut buf);
        assert_eq!(buf[(0, 0)].symbol(), "▀");
        assert_eq!(buf[(0, 0)].fg, Color::Rgb(0, 0, 0));
        assert_eq!(buf[(3, 0)].symbol(), " ", "transparent cells are untouched");
    }
}
